import { ReactElement, useState } from 'react';

import {
  DONUT_LABEL_MAX_ANCHOR_OFFSET_RATIO,
  DONUT_LABEL_RING_GAPS,
  DONUT_SIZE_TIER_CUTPOINTS,
} from '@spectrum-charts/constants';
import { ChartData } from '@spectrum-charts/vega-spec-builder-s2';

import { Chart } from '../../../Chart';
import useChartProps from '../../../hooks/useChartProps';
import { Donut } from '../../../pre-alpha';
import { DonutProps } from '../../../types';

const THUMB_HEIGHT = 32;
const REACH_RATIO = 1 + DONUT_LABEL_MAX_ANCHOR_OFFSET_RATIO;

const getLabelRingGapForDiameter = (diameter: number): number =>
  DONUT_LABEL_RING_GAPS[DONUT_SIZE_TIER_CUTPOINTS.filter((cutpoint) => diameter >= cutpoint).length];

/** Mirrors the spec builder: use the highest tier whose own gap still keeps the donut in that tier. */
export const getEffectiveDiameter = (containerWidth: number): number => {
  const rawRadius = containerWidth / 2 - 2;
  const getDiameter = (gap: number): number => (2 * (rawRadius - gap)) / REACH_RATIO;
  const gap = DONUT_LABEL_RING_GAPS.reduce(
    (selectedGap, tierGap, tier) =>
      tier > 0 && getDiameter(tierGap) >= DONUT_SIZE_TIER_CUTPOINTS[tier - 1] ? tierGap : selectedGap,
    DONUT_LABEL_RING_GAPS[0]
  );
  return getDiameter(gap);
};

export const getContainerWidthForDiameter = (diameter: number): number =>
  diameter * REACH_RATIO + 4 + 2 * getLabelRingGapForDiameter(diameter);

const lastCutpoint = DONUT_SIZE_TIER_CUTPOINTS.at(-1);
if (lastCutpoint === undefined) {
  throw new Error('DONUT_SIZE_TIER_CUTPOINTS must not be empty');
}
const MAX_TIER_CUTPOINT = lastCutpoint;
const CHART_SIZE = getContainerWidthForDiameter(MAX_TIER_CUTPOINT) + 50;
const MAX_WIDTH = CHART_SIZE + 100;

const HANDLE_STYLES = `
  .rsc-dl-size-handle {
    -webkit-appearance: none;
    appearance: none;
    background: transparent;
    border: none;
    outline: none;
    position: absolute;
    top: 0;
    left: 0;
    height: ${CHART_SIZE}px;
    pointer-events: none;
    z-index: 20;
  }
  .rsc-dl-size-handle::-webkit-slider-runnable-track {
    background: transparent;
    height: ${CHART_SIZE}px;
  }
  .rsc-dl-size-handle::-webkit-slider-thumb {
    -webkit-appearance: none;
    width: 8px;
    height: ${THUMB_HEIGHT}px;
    border-radius: 4px;
    background: #999;
    cursor: ew-resize;
    pointer-events: all;
    margin-top: ${(CHART_SIZE - THUMB_HEIGHT) / 2}px;
  }
  .rsc-dl-size-handle::-moz-range-track { background: transparent; }
  .rsc-dl-size-handle::-moz-range-thumb {
    width: 8px;
    height: ${THUMB_HEIGHT}px;
    border-radius: 4px;
    background: #999;
    border: none;
    cursor: ew-resize;
  }
`;

const TIER_LABELS = ['XS', 'S', 'M', 'L', 'XL'];
const THRESHOLDS = DONUT_SIZE_TIER_CUTPOINTS.map((cutpoint, i) => ({
  px: getContainerWidthForDiameter(cutpoint),
  label: TIER_LABELS[i + 1],
  diameter: cutpoint,
}));

const getSizeTier = (containerWidth: number): string => {
  const diameter = getEffectiveDiameter(containerWidth);
  const index = DONUT_SIZE_TIER_CUTPOINTS.findIndex((cutpoint) => diameter < cutpoint);
  if (index !== -1) return TIER_LABELS[index];
  const lastLabel = TIER_LABELS.at(-1);
  if (lastLabel === undefined) {
    throw new Error('TIER_LABELS must not be empty');
  }
  return lastLabel;
};

export const ResponsiveDonut = ({
  data,
  donutProps,
  children,
  initialWidth = 300,
}: {
  data: ChartData[];
  donutProps?: Partial<DonutProps>;
  children: DonutProps['children'];
  initialWidth?: number;
}): ReactElement => {
  const [width, setWidth] = useState(initialWidth);
  const chartProps = useChartProps({ data });
  const outerDiameter = getEffectiveDiameter(width);
  const currentSize = getSizeTier(width);

  return (
    <div style={{ padding: '16px 0' }}>
      <style>{HANDLE_STYLES}</style>
      <div style={{ marginBottom: 8, fontSize: 13, color: '#666' }}>
        Container Width: <strong>{Math.round(width)}px</strong> — Outer Diameter:{' '}
        <strong>{Math.round(outerDiameter)}px</strong> — Size tier: <strong>{currentSize}</strong>
      </div>
      <div style={{ position: 'relative', minWidth: MAX_WIDTH }}>
        {THRESHOLDS.map(({ px, label, diameter }) => (
          <div
            key={label}
            style={{
              position: 'absolute',
              left: px,
              top: 0,
              bottom: 0,
              width: 1,
              background: 'rgba(220, 60, 60, 0.6)',
              zIndex: 10,
              pointerEvents: 'none',
            }}
          >
            <span
              style={{
                position: 'absolute',
                top: 2,
                left: 3,
                fontSize: 10,
                color: 'rgba(220, 60, 60, 0.9)',
                whiteSpace: 'nowrap',
                lineHeight: 1,
              }}
            >
              {label} ({diameter}px)
            </span>
          </div>
        ))}
        <div style={{ position: 'relative', display: 'inline-block' }}>
          <Chart {...chartProps} width={width} height={CHART_SIZE}>
            <Donut metric="count" color="browser" {...donutProps}>
              {children}
            </Donut>
          </Chart>
          <input
            type="range"
            className="rsc-dl-size-handle"
            aria-label="Chart width"
            min={0}
            max={MAX_WIDTH}
            value={Math.round(width)}
            onChange={(event) => setWidth(Math.max(50, Number(event.target.value)))}
            style={{ width: MAX_WIDTH }}
          />
        </div>
      </div>
    </div>
  );
};
